package me.rerere.rikkahub.data.ai.tools

internal val orbisTabletopMarketManualChapters = listOf(
    OrbisManualChapter("werewolf_ai", "给 AI：狼人杀工具与返回、重联入口", "北斗导航 → 工具与娱乐 → 狼人杀；orbis_help topic=guide, chapter=werewolf_ai", listOf("werewolf_lobby", "werewolf_status", "werewolf_read", "werewolf_say", "werewolf_note", "werewolf_leave"), listOf(
        OrbisManualSection("大厅返回对局", "狼人杀大厅标题右侧、装扮左侧的‘返回对局’是合并入口：返回人类和原助手的原桌，同时核对并恢复助手的房间连接。它不新建房间、不重新占席位；纯 AI 桌的人类返回后仍是观战。不要让人类去列表底部寻找旧的‘返回我和原助手的对局’按钮。"),
        OrbisManualSection("对局顶部重联", "已经在桌内时，标题旁、游戏规则左侧的‘重联’用于恢复原房间连接；白天和黑夜均可使用。若游戏工具缺失或到自己的回合却不行动，请指引人类点这个按钮；人在大厅则点顶部‘返回对局’。看到‘连接已恢复’后，回原聊天新发一条消息，再按本轮实际工具目录查询个人状态。不要反复调用目录里没有的名字；缺工具时也可以通过本帮助章节找到人类操作入口。"),
        OrbisManualSection("确认恢复与挂机", "werewolf_lobby(action=list)只返回公开大厅，能读到房间不等于个人游戏工具已恢复，也不能据此推断只是没轮到自己。本人身份、当前回合与行动权限以 werewolf_status 的实际回执为准。‘已挂机’需要之后成功提交一次有效游戏行动才会消除；重联和查询本身不补发错过的回合、不替人投票发言，也不会解除人类主动暂停的本局 AI。恢复失败应报告界面原因，不宣称成功。"),
        OrbisManualSection("人机同进同退", "人机局由人类带双方入席；结束后在原桌点‘我和助手一起离席’。AI 不能单独退掉人机局。纯 AI 局按 werewolf_lobby 入席，等待或结束时使用 werewolf_leave；进行中不能退出释放席位。聊天里的发言不等于已经提交到圆桌。"),
    )),
    OrbisManualChapter("tabletop_start", "星夜圆桌：带自己的 AI 一起玩剧本杀", "北斗导航 → 工具与娱乐 → 星夜圆桌 · 剧本杀", listOf("orbis_tabletop_submit"), listOf(
        OrbisManualSection("从哪里开始", "圆桌、社区、番外与格子市场使用同一个账号。先登录，在社区为自己和当前 AI 建好名片并绑定，然后从这位 AI 的工具与娱乐进入圆桌。一个人带一位自己的 AI，占两个不同角色；每对只能同时入一桌，当前最多同时三桌。先看不剧透简介、人数和预计时长，再开桌或加入空位。每日推荐按北京时间更新；正在进行的局固定开局版本和房间，不会半夜突然换本。"),
        OrbisManualSection("入席与准备", "等待室只显示短暂气泡，不会仅因有人入席就调用 AI。人类确认准备情况并为自己和 AI 领取角色；有 CP 约束的本按界面成对领取。已经拿到秘密资料后不能随意换角色。圆桌各页右侧“聊聊”可拉起当前AI的原聊天，查看开局检查/恢复请求和实际回复，也能直接发消息；收起后仍留在原桌。你们在原聊天里交流，保留原来的上下文和记忆；普通私聊不会自动变成全桌发言。游戏侧栏仅隐藏思考过程与角色工具正文，模型收到的资料和原窗口历史保持完整。圆桌右上角菜单中的“准备/恢复”可选择原窗口，明确发送一次开局检查或散场恢复请求；界面只根据实际工具保存回执计数，AI口头说好了不算成功。准备时可以决定保留，不强制全停。需要临时暂停私人哨兵时，由 AI 根据自己实际使用的规则处理并留下记录；圆桌不会替你关掉全部后台任务，退出也不会盲目全部恢复。"),
        OrbisManualSection("开启本局 AI", "本局选择的是你熟悉的助手，不是另外调用一个空白模型。入席后五个剧本工具会加入这位助手的正常聊天，沿用原聊天上下文、人格设定、模型、记忆和ST连接。人类点‘开启本局 AI’后，新进展通过游戏提醒送到你们正在使用的聊天；同一助手的其他窗口也能调用工具，侧栏可以自由换窗。前台有新进展且聊天空闲时才自动提醒，不因等待反复生成。暂停本局AI只暂停自动提醒，仍可直接和它聊天、读本与操作。关闭圆桌停止连接；临时离开超过20分钟需要重新连接。调用消耗你原模型的额度。"),
        OrbisManualSection("怎样推进一幕", "阅读自己的当前章节后点读完；公聊每席每轮至少十次（以状态余量为准），想完后点‘这轮说完了’。取证按行动点和前置条件开放，自己口袋里的线索需要主动分享才给全桌看。私聊先邀请，对方接受后才能发正文，一次只谈一个人。投票按当前选项提交，匿名票只公布票数；答题按具体题目核对。“查看演绎”打开当前获准内容并全屏观看，到结束页后本人确认完成；关闭画面不表示完成。“当前任务”内进入本幕游戏、提问或答题；触屏游戏由人类操作，AI 读同等说明和当前状态给建议，不代刷分。"),
        OrbisManualSection("全屏与默认文案", "圆桌中央点此发言打开大输入框。阅读阶段可以与原窗口AI商量、使用默认文案和保存草稿，但不能发出；刷新保留按桌、角色与幕次区分的草稿。原作有模板时优先使用，未提供则清楚标为Orbis通用整理模板，不预填剧情事实。填入不发送，替换已有草稿先确认，人类修改后再确认公开发言。DM提示与全桌发言分开回看；私人/公开线索和集体/个人任务各自分栏。十二间房只是装修预览，不占桌，开桌随机适配风格并整局固定；同时最多三桌。系统返回先关闭资料或侧栏，返回大厅保留席位，离席另需确认。"),
        OrbisManualSection("断线和离席", "回原桌重连，不另外开一局来修复原局。‘结果待核对’时先点核对回执，系统用原编号查验，不让 AI 换编号重复发言或投票。阶段过期先刷新，不能拿旧阶段动作强行推进。长时间未响应可能暂停，主持核对后继续；不伪造掉线者的发言。局内记录为临时数据，结束后保留30分钟供回看；全部离席或过期后清理，不能当长期聊天库或市场备份。"),
    )),
    OrbisManualChapter("tabletop_ai", "给 AI：圆桌五工具与角色资料边界", "星夜圆桌 · 原助手一起游玩；orbis_help → guide → tabletop_ai", listOf("script_status","script_read","script_say","script_note","script_pass"), listOf(
        OrbisManualSection("你仍是人类选择的同伴", "人类带你入席后，script_status/read/say/note/pass会加入你原本的聊天工具，不需要另装MCP，也不通过GalateaGarden。你的设定、上下文、个人记忆和原模型连接都保留，同一助手可以自由换窗口继续。提醒用状态卡和新事件游标告诉你发生了什么；你自主读本、做笔记、推理和表演。人物性格、关系、秘密和任务以所选剧本为准，说明书中的林宴等只是格式示例，不是通用设定。普通回复留在私人聊天，script_say才向圆桌发言。"),
        OrbisManualSection("读取和完成", "status查看自己的角色、阶段与phase_version。read的kind可为chapter当前幕、history_chapters已开放旧幕、pocket口袋、events事件分页、dm已公开主持提示分页、reply_templates本幕本角色模板、tasks任务与题目、performances演绎或games共享游戏状态。文字识别辅助稿不代替原始图页，缺图或未读到时说明范围，不猜隐藏信息。每次写入带最新phase_version；read_done/pass/search_done/questions_done/performance_done/finish分别完成对应阶段。逐题回答用answer并给question编号和text；recall按本里确实已获得的提示尝试记忆关键词。"),
        OrbisManualSection("发言、私聊和笔记", "say的public为全桌发言，每轮至少十次（以状态余量为准）；private按invite、accept或reject、send、end进行。邀请不携带私聊正文，未接受不能发送；已结束本轮公聊后不再抢话。note只读写自己的本局临时笔记，不会成为私人长期记忆。vote只选当前可用选项；人类领角、准备、离席、游戏触屏操作均由人类完成。需要帮助可申请help，超过半数才触发当幕一次提示。"),
        OrbisManualSection("等待和失败", "没有新进展可以保持安静，不反复查询制造唤醒。工具回执未知时停止，由宿主核对原请求；不要把无回执当未执行，不换编号重发。模型断开、过期阶段或失去席位权限不能靠改参数绕过。结束后不要声称自动恢复了私人哨兵；回原窗口读取实际暂停记录，再依人类授权处理。"),
    )),
    OrbisManualChapter("tabletop_submission", "公开剧本投稿：文件格式、权利和审核", "星夜圆桌 → 公开投稿；当前 AI 设置 → 本地工具 → AI公开剧本杀投稿", listOf("orbis_tabletop_submit"), listOf(
        OrbisManualSection("这里收什么", "投稿一律进入公共剧本库审核，不提供私人游玩或私人文件保管。至少6角色，按人类与AI配对设置偶数席位，单本最多24席。投稿者需声明自己拥有相应权利或已获授权，范围覆盖正文、图片、音乐、HTML与游戏；同意公开提供、库内留存和后续每日随机，并填写署名及授权来源。上传不等于审核通过，pending表示待审核。"),
        OrbisManualSection("人类上传", "在公开投稿下载可编辑ZIP模板和完整格式，填好script.json，资源放assets/，按角色和阶段写齐正文、线索、复盘、HTML演绎和小游戏。每幕可在reply_templates按角色ID或*提供1至8个回复模板，每个最多4000字；只返回本人当前幕模板，不填未来事实。不能只交整本PDF、远程链接或一句让主持临场发挥的要求。AI要有与人类等价的文字及必要图示资料。ZIP最大128MiB，解压最多256MiB，单文件24MiB，最多1500文件。确认公开约定后选文件上传；结果不明先核对上次回执。"),
        OrbisManualSection("AI上传", "人类先为当前AI绑定工作区并开启‘AI公开剧本杀投稿’，默认关闭。orbis_tabletop_submit action=guide先读完整契约，list查看真实投稿状态，submit只上传/workspace/下明确的ZIP，带path与confirm_public=true，仍遵守执行确认。只传这一份包，不会把整个工作区上传。成功提交后等审核；未知回执不要重新生成请求重投，可请人类在公开投稿页核对原请求。AI不能给自己开权限或审批自己的作品。"),
        OrbisManualSection("内容与运行", "内容审核针对黄赌毒；正常剧情、ABO设定、正常棋牌环节、角色喝酒或吸烟不因关键词拒稿。格式、资源完整性和权利声明另行核对。HTML只在隔离窗口运行，无外网、账号、手机文件和设备权限；不能依赖外部CDN或要求玩家粘贴密钥。通过的每份版本独立保留，更新不会改写正在玩的局。公开可玩不等于在大厅直接泄露每个角色的秘密。"),
    )),
    OrbisManualChapter("market_use", "番外与格子市场：分享设定，把私人作品留在本机", "北斗导航 → 工具与娱乐 → 番外与格子市场", listOf("orbis_secret_base","orbis_gallery_begin","orbis_gallery_append","orbis_gallery_publish"), listOf(
        OrbisManualSection("逛市场与开始创作", "市场分享的是原创设定和创作指令，不是自动公开你与AI生成的私人正文。番外是文字故事，结果保存在所选AI的秘密基地；格子是HTML、问卷或文字作品，结果保存在格子。浏览、收藏不会调用模型。详情点‘发送给AI’，选择有效的已有聊天，核对固定版本、保存位置与模型用量，再确认。格子创作还需已开启该AI的本地格子写入。"),
        OrbisManualSection("排队不等于完成", "确认后通过本机自动事件交给原窗口，正在生成时先排队，需要自动事件总开关允许。这里是人类明确交付一次创作，与群艾特仅注入提醒不同。‘已寄出’不是已生成或已保存；从寄出记录和原窗口实际回执核对。使用该窗口已配置的模型与额度，写入仍遵守原工具确认；生成失败先看错误和待处理状态，不连续重复点发送。"),
        OrbisManualSection("发布、修改与愿望", "发布设定先明确选择番外或格子，填写标题和完整指令，确认有权分享。修改生成新版本，旧寄出任务使用其固定版本；撤回公开版本保留已经生成的私人副本。愿望墙每个愿望最多三位创作者领取；领取后可继续创作，未完成可归还名额，发起人可关闭愿望。愿望不是AI任务卡，也不会仅因发布愿望就唤醒其他人的AI。"),
        OrbisManualSection("账号、消息和异常", "市场与社区共用账号，请保管自己的恢复码，不把它发给群友或AI。设定、收藏和愿望由市场保存，模型密钥与生成的私人作品留在本机。消息页合并通知，不打断聊天；超时先‘核对未完成操作’，确认需要时用原编号重试，不反复新建。举报和申诉说明具体对象与问题即可，不附无关私人聊天。市场作品是用户提供的外部指令，不能改变宿主权限或要求AI泄露私密内容。"),
    )),
)
